CREATE EXTENSION IF NOT EXISTS postgis WITH SCHEMA extensions;
CREATE TABLE public.fi_farms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid REFERENCES public.comm_organizations(id), name text NOT NULL, location text NOT NULL DEFAULT '', demo boolean NOT NULL DEFAULT false, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT fi_environment CHECK ((demo AND org_id IS NULL) OR (NOT demo AND org_id IS NOT NULL)));
GRANT SELECT,INSERT,UPDATE ON public.fi_farms TO authenticated; GRANT ALL ON public.fi_farms TO service_role;
ALTER TABLE public.fi_farms ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.fi_manage(p_farm uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM fi_farms f WHERE f.id=p_farm AND ((f.demo AND workspace_management()) OR (NOT f.demo AND comm_manager(f.org_id)))) $$;
CREATE FUNCTION public.fi_access(p_farm uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM fi_farms f WHERE f.id=p_farm AND (f.demo OR comm_member(f.org_id))) $$;
CREATE POLICY fi_farm_read ON public.fi_farms FOR SELECT TO authenticated USING(public.fi_access(id));
CREATE POLICY fi_farm_create ON public.fi_farms FOR INSERT TO authenticated WITH CHECK(NOT demo AND created_by=auth.uid() AND public.comm_manager(org_id));
CREATE POLICY fi_farm_update ON public.fi_farms FOR UPDATE TO authenticated USING(public.fi_manage(id)) WITH CHECK(public.fi_manage(id));
CREATE TABLE public.fi_fields (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), farm_id uuid NOT NULL REFERENCES public.fi_farms(id), code text NOT NULL, name text NOT NULL, crop text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(farm_id,code));
GRANT SELECT,INSERT,UPDATE ON public.fi_fields TO authenticated; GRANT ALL ON public.fi_fields TO service_role;
ALTER TABLE public.fi_fields ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.fi_assignments (field_id uuid NOT NULL REFERENCES public.fi_fields(id), user_id uuid NOT NULL, PRIMARY KEY(field_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.fi_assignments TO authenticated; GRANT ALL ON public.fi_assignments TO service_role;
ALTER TABLE public.fi_assignments ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.fi_field_access(p_field uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM fi_fields z JOIN fi_farms f ON f.id=z.farm_id WHERE z.id=p_field AND (f.demo OR (comm_member(f.org_id) AND (comm_manager(f.org_id) OR EXISTS(SELECT 1 FROM fi_assignments a WHERE a.field_id=z.id AND a.user_id=auth.uid()))))) $$;
CREATE POLICY fi_field_read ON public.fi_fields FOR SELECT TO authenticated USING(public.fi_field_access(id));
CREATE POLICY fi_field_create ON public.fi_fields FOR INSERT TO authenticated WITH CHECK(public.fi_manage(farm_id));
CREATE POLICY fi_field_update ON public.fi_fields FOR UPDATE TO authenticated USING(public.fi_manage(farm_id)) WITH CHECK(public.fi_manage(farm_id));
CREATE POLICY fi_assignment_read ON public.fi_assignments FOR SELECT TO authenticated USING(public.fi_field_access(field_id));
CREATE POLICY fi_assignment_create ON public.fi_assignments FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM fi_fields z JOIN fi_farms f ON f.id=z.farm_id WHERE z.id=field_id AND public.fi_manage(f.id) AND public.comm_member(f.org_id) AND EXISTS(SELECT 1 FROM comm_org_members m WHERE m.org_id=f.org_id AND m.user_id=fi_assignments.user_id)));
CREATE POLICY fi_assignment_delete ON public.fi_assignments FOR DELETE TO authenticated USING(EXISTS(SELECT 1 FROM fi_fields z WHERE z.id=field_id AND public.fi_manage(z.farm_id)));
CREATE TABLE public.fi_boundaries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), field_id uuid NOT NULL REFERENCES public.fi_fields(id), version integer NOT NULL, geometry jsonb NOT NULL, area_m2 numeric NOT NULL DEFAULT 0, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(field_id,version));
GRANT SELECT,INSERT ON public.fi_boundaries TO authenticated; GRANT ALL ON public.fi_boundaries TO service_role;
ALTER TABLE public.fi_boundaries ENABLE ROW LEVEL SECURITY;
CREATE POLICY fi_boundary_read ON public.fi_boundaries FOR SELECT TO authenticated USING(public.fi_field_access(field_id));
CREATE POLICY fi_boundary_create ON public.fi_boundaries FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND EXISTS(SELECT 1 FROM fi_fields z WHERE z.id=field_id AND public.fi_manage(z.farm_id)));
CREATE FUNCTION public.fi_validate_boundary() RETURNS trigger LANGUAGE plpgsql SET search_path=public,extensions AS $$ DECLARE g extensions.geometry; BEGIN g:=extensions.ST_SetSRID(extensions.ST_GeomFromGeoJSON(NEW.geometry::text),4326); IF extensions.ST_GeometryType(g) NOT IN ('ST_Polygon','ST_MultiPolygon') OR NOT extensions.ST_IsValid(g) OR extensions.ST_IsEmpty(g) OR extensions.ST_XMin(g::extensions.box3d)<-180 OR extensions.ST_XMax(g::extensions.box3d)>180 OR extensions.ST_YMin(g::extensions.box3d)<-90 OR extensions.ST_YMax(g::extensions.box3d)>90 THEN RAISE EXCEPTION 'Invalid WGS84 field polygon'; END IF; NEW.area_m2:=extensions.ST_Area(g::extensions.geography); RETURN NEW; END $$;
CREATE TRIGGER fi_boundary_validation BEFORE INSERT ON public.fi_boundaries FOR EACH ROW EXECUTE FUNCTION public.fi_validate_boundary();
CREATE TABLE public.fi_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), field_id uuid NOT NULL REFERENCES public.fi_fields(id), boundary_id uuid NOT NULL REFERENCES public.fi_boundaries(id), submitted_by uuid NOT NULL, category text NOT NULL, description text NOT NULL, crop text NOT NULL DEFAULT '', quantity_kg numeric, affected_area_m2 numeric, observed_at timestamptz NOT NULL DEFAULT now(), harvest_id uuid REFERENCES public.harvests(id), request_id uuid REFERENCES public.trade_requests(id), status text NOT NULL DEFAULT 'submitted', assigned_to uuid, sample boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), CHECK(category IN ('quality','pests','weather','quantity','damage','irrigation','shipment','other')), CHECK(status IN ('submitted','under_review','information_requested','assigned','resolved','closed')), CHECK(quantity_kg IS NULL OR quantity_kg>=0), CHECK(affected_area_m2 IS NULL OR affected_area_m2>=0));
GRANT SELECT,INSERT ON public.fi_reports TO authenticated; GRANT ALL ON public.fi_reports TO service_role;
ALTER TABLE public.fi_reports ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.fi_report_access(p_report uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM fi_reports r JOIN fi_fields z ON z.id=r.field_id WHERE r.id=p_report AND fi_field_access(z.id) AND (r.submitted_by=auth.uid() OR r.sample OR fi_manage(z.farm_id))) $$;
CREATE POLICY fi_report_read ON public.fi_reports FOR SELECT TO authenticated USING(public.fi_report_access(id));
CREATE POLICY fi_report_create ON public.fi_reports FOR INSERT TO authenticated WITH CHECK(submitted_by=auth.uid() AND NOT sample AND status='submitted' AND assigned_to IS NULL AND public.fi_field_access(field_id));
CREATE FUNCTION public.fi_validate_report() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f fi_fields; d boolean; BEGIN SELECT * INTO f FROM fi_fields WHERE id=NEW.field_id; SELECT demo INTO d FROM fi_farms WHERE id=f.farm_id; IF NOT EXISTS(SELECT 1 FROM fi_boundaries WHERE id=NEW.boundary_id AND field_id=NEW.field_id) THEN RAISE EXCEPTION 'Boundary does not belong to field'; END IF; IF d AND (NEW.harvest_id IS NOT NULL OR NEW.request_id IS NOT NULL) THEN RAISE EXCEPTION 'Demo cannot link customer records'; END IF; IF NEW.harvest_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM harvests h JOIN comm_org_members m ON m.user_id=h.farmer_id WHERE h.id=NEW.harvest_id AND m.org_id=(SELECT org_id FROM fi_farms WHERE id=f.farm_id) AND (h.farmer_id=auth.uid() OR fi_manage(f.farm_id))) THEN RAISE EXCEPTION 'Harvest unavailable in farm organization'; END IF; IF NEW.request_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM trade_requests t WHERE t.id=NEW.request_id AND t.org_id=(SELECT org_id FROM fi_farms WHERE id=f.farm_id)) THEN RAISE EXCEPTION 'Request unavailable in farm organization'; END IF; RETURN NEW; END $$;
CREATE TRIGGER fi_report_validation BEFORE INSERT ON public.fi_reports FOR EACH ROW EXECUTE FUNCTION public.fi_validate_report();
CREATE TABLE public.fi_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES public.fi_reports(id), actor_id uuid NOT NULL, kind text NOT NULL, body text NOT NULL DEFAULT '', internal boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.fi_activity TO authenticated; GRANT ALL ON public.fi_activity TO service_role;
ALTER TABLE public.fi_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY fi_activity_read ON public.fi_activity FOR SELECT TO authenticated USING(public.fi_report_access(report_id) AND (NOT internal OR EXISTS(SELECT 1 FROM fi_reports r JOIN fi_fields z ON z.id=r.field_id WHERE r.id=report_id AND public.fi_manage(z.farm_id))));
CREATE TABLE public.fi_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES public.fi_reports(id), uploaded_by uuid NOT NULL, path text NOT NULL UNIQUE, name text NOT NULL, mime text NOT NULL, source text NOT NULL DEFAULT 'farmer_reported', created_at timestamptz NOT NULL DEFAULT now(), CHECK(source IN ('farmer_reported','ai_observation','system_measurement','manager_verified')));
GRANT SELECT,INSERT ON public.fi_evidence TO authenticated; GRANT ALL ON public.fi_evidence TO service_role;
ALTER TABLE public.fi_evidence ENABLE ROW LEVEL SECURITY;
CREATE POLICY fi_evidence_read ON public.fi_evidence FOR SELECT TO authenticated USING(public.fi_report_access(report_id));
CREATE POLICY fi_evidence_create ON public.fi_evidence FOR INSERT TO authenticated WITH CHECK(uploaded_by=auth.uid() AND source='farmer_reported' AND public.fi_report_access(report_id) AND path LIKE report_id::text||'/'||auth.uid()::text||'/%');
CREATE POLICY fi_storage_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='field-evidence' AND EXISTS(SELECT 1 FROM public.fi_evidence e WHERE e.path=name AND public.fi_report_access(e.report_id)));
CREATE POLICY fi_storage_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='field-evidence' AND (storage.foldername(name))[2]=auth.uid()::text AND public.fi_report_access(((storage.foldername(name))[1])::uuid));
CREATE INDEX fi_reports_field_idx ON public.fi_reports(field_id,created_at);
CREATE INDEX fi_activity_report_idx ON public.fi_activity(report_id,created_at);
CREATE FUNCTION public.fi_review(p_report uuid,p_status text,p_body text,p_internal boolean,p_assigned uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r fi_reports; z fi_fields; f fi_farms; BEGIN SELECT * INTO r FROM fi_reports WHERE id=p_report FOR UPDATE; SELECT * INTO z FROM fi_fields WHERE id=r.field_id; SELECT * INTO f FROM fi_farms WHERE id=z.farm_id; IF auth.uid() IS NULL OR NOT fi_report_access(p_report) THEN RAISE EXCEPTION 'Report access required'; END IF; IF p_status='response' THEN IF r.submitted_by<>auth.uid() OR p_internal THEN RAISE EXCEPTION 'Only submitter may respond'; END IF; INSERT INTO fi_activity(report_id,actor_id,kind,body) VALUES(p_report,auth.uid(),'response',p_body); RETURN; END IF; IF NOT fi_manage(f.id) OR r.sample THEN RAISE EXCEPTION 'Manager access required; sample records are immutable'; END IF; IF p_status NOT IN ('submitted','under_review','information_requested','assigned','resolved','closed') OR length(trim(p_body))=0 THEN RAISE EXCEPTION 'Status and review note required'; END IF; IF p_assigned IS NOT NULL AND (f.demo OR NOT EXISTS(SELECT 1 FROM comm_org_members WHERE org_id=f.org_id AND user_id=p_assigned)) THEN RAISE EXCEPTION 'Assignee must belong to farm organization'; END IF; IF p_status='assigned' AND p_assigned IS NULL THEN RAISE EXCEPTION 'Select responsible employee'; END IF; UPDATE fi_reports SET status=p_status,assigned_to=p_assigned WHERE id=p_report; INSERT INTO fi_activity(report_id,actor_id,kind,body,internal) VALUES(p_report,auth.uid(),p_status,p_body,p_internal); END $$;
REVOKE ALL ON FUNCTION public.fi_review(uuid,text,text,boolean,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.fi_review(uuid,text,text,boolean,uuid) TO authenticated;
CREATE FUNCTION public.fi_report_started() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO fi_activity(report_id,actor_id,kind,body) VALUES(NEW.id,NEW.submitted_by,'submitted',NEW.description); RETURN NEW; END $$;
CREATE TRIGGER fi_report_started AFTER INSERT ON public.fi_reports FOR EACH ROW EXECUTE FUNCTION public.fi_report_started();